public static void checkJSONObjectsMaps_1_oe(List<JSONObject> jsonObjects) {
        if (jsonObjects == null || jsonObjects.size() == 0) {
            return;
        }
        Class<? extends Map> mapType = new JSONObject().getMapType();
        for (JSONObject jsonObject : jsonObjects) {
            if (jsonObject != null) {
                assertTrue(mapType == jsonObject.getMapType());
}
}
}

public static void checkJSONObjectMaps_1_oe(JSONObject jsonObject, Class<? extends Map> mapType) {
        if (mapType == null) {
            mapType = new JSONObject().getMapType();
        }
        Set<String> keys = jsonObject.keySet();
        for (String key : keys) {
            Object val = jsonObject.get(key);
            if (val instanceof JSONObject) {
                JSONObject jsonObjectVal = (JSONObject) val;
                assertTrue(mapType == ((JSONObject) val).getMapType());
}
}
}

private void compareFileToJSONObject_1_oe(String xmlStr, String expectedStr) {
        try {
            JSONObject expectedJsonObject = new JSONObject(expectedStr);
            File tempFile = this.testFolder.newFile("fileToJSONObject.xml");
            FileWriter fileWriter = new FileWriter(tempFile);
            try {
                fileWriter.write(xmlStr);
            } finally {
                fileWriter.close();
            }

            Reader reader = new FileReader(tempFile);
            try {
                JSONObject jsonObject = XML.toJSONObject(reader);
                Util.compareActualVsExpectedJsonObjects(jsonObject,expectedJsonObject);
            } finally {
                reader.close();
            }
        } catch (IOException e) {
            fail("Error: " +e.getMessage());
}
}

private void compareReaderToJSONObject_1_oe(String xmlStr, String expectedStr,
            XMLParserConfiguration config) {
        /*
         * Commenting out this method until the JSON-java code is updated
         * to support XML.toJSONObject(reader)
         */
        JSONObject expectedJsonObject = new JSONObject(expectedStr);
        Reader reader = new StringReader(xmlStr);
        try {
            JSONObject jsonObject = XML.toJSONObject(reader, config);
            Util.compareActualVsExpectedJsonObjects(jsonObject,expectedJsonObject);
        } catch (Exception e) {
            assertTrue("Reader error: " +e.getMessage(), false);
}
}

